int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");static_assert(sizeof(void*)==8,"x64 required");auto graph=loadGraph(argv[1]);RecoveredOwnedDmxReferenceProjectionCandidate<Graph>p(graph,[](const std::string&,auto&){return 0xffffffffu;});auto serial=graph;unsigned checks=0;
 for(uint32_t i=0;i<graph.elements.size();++i){const auto&e=graph.elements[i];if(graph.strings.at(e.type)!="DmeExpressionOperator")continue;const auto*input=namedAttribute(graph,e,"value");const auto*output=namedAttribute(graph,e,"result");if(!input||input->type!=3||!output)continue;auto*owner=p.scene.resolve(p.elementHandles[i]);owner->registration.state=0xa0;
 for(float value:{0.25f,0.75f}){const float previous=wireFloat(namedAttribute(p.graph,p.graph.elements[i],"value")->values[0]);const bool changed=floatMutationNeeded(previous,value);if(p.setScalarFloat(i,"value",value,0)!=changed)throw std::runtime_error("owned input write mismatch");if(!changed)continue;OperatorAttributeRegistration r;r.add(p.elementHandles[i],{},{});unsigned executions=0;auto schedule=buildRegisteredOperators(r,{},[&](uintptr_t){return expressionOperatorDirtyCandidate(owner->registration.state);},[&](uintptr_t){clearExpressionOperatorDirtyCandidate(owner->registration.state);},[](uintptr_t)->uint16_t&{throw std::runtime_error("unexpected attribute lookup");},[](uintptr_t,size_t){});if(schedule.identities.size()!=1)throw std::runtime_error("edited expression not selected");serial.elements[i]=p.graph.elements[i];const auto expected=sampleSessionExpression(serial,i);executeSessionExpression(serial,i);for(auto id:schedule.identities){if(id!=p.elementHandles[i])throw std::runtime_error("selected wrong expression");const auto actual=executeOwnedSessionExpressionCandidate(p,i,4);if(actual.success!=expected.success||std::memcmp(&actual.result,&expected.result,4))throw std::runtime_error("owned expression sample mismatch");++executions;}const float actual=wireFloat(namedAttribute(p.graph,p.graph.elements[i],"result")->values[0]);const float result=wireFloat(namedAttribute(serial,serial.elements[i],"result")->values[0]);if(std::memcmp(&actual,&result,4)||executions!=1)throw std::runtime_error("owned result commit mismatch");++checks;}
 }if(!checks)throw std::runtime_error("no expression inputs exercised");std::cout<<"owned_expression_edit_execute_checks="<<checks<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
